 if(!$errors){$u=$pdo->prepare('UPDATE USERS SET FirstName=:first, LastName=:last, Phone=:phone, CareerField=:career WHERE UserID=:id AND UserStatus=\'active\'');$u->execute(['first'=>$first?:null,'last'=>$last?:null,'phone'=>$phone?:null,'career'=>$career?:null,'id'=>$user_id]);$success='Profile updated.';$q->execute(['id'=>$user_id]);$user=$q->fetch(PDO::FETCH_ASSOC);}
